contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, bytes32 role) public {
        // Precondition: we only test accounts with no roles in a fresh deployment.
        // Fresh deployment has no grants, so this always holds.
        require(account != address(0), "zero address");
        require(role != bytes32(0), "zero role");

        // Pre-values read via public view surface.
        bool adminBefore = c.hasRole(role, account);
        bool ownerBefore = c.owner() == account;

        // The deciding state-changing call: grantRole by non-admin msg.sender.
        // Because msg.sender is not admin, this must revert; but the rule is
        // about state being unchanged even in the revert case.
        try c.grantRole(role, account) {
            // If call unexpectedly succeeds, record that fact; no catches nested.
        } catch {
        }

        // Post-values read via the same public surface.
        bool adminAfter = c.hasRole(role, account);
        bool ownerAfter = c.owner() == account;

        // General rule: a grantRole call does not change admin/owner status
        // for an arbitrary (account,role) in this fresh contract.
        assert(adminBefore == adminAfter && ownerBefore == ownerAfter);
    }
}

