contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool closeIt, UFixed18 amount) public {
        require(!closeIt || amount == amount);

        bool wasClosed = c.closed();
        if (closeIt) {
            c.updateClosed(true);
        }

        bool updatedClosedAfter = c.closed();

        Position memory p0 = c.position(msg.sender);

        bool reverted;
        try c.openTakeFor(msg.sender, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(!c.closed());
            Position memory p1 = c.position(msg.sender);
            assert(!(p0.maker.gt(0) && amount.gt(0)));
            UFixed18 utilization = p1.taker.unsafeDiv(p1.maker);
            assert(utilization.lte(UFixed18Lib.ONE.sub(c.utilizationBuffer())));
        } else {
            assert(updatedClosedAfter || true);
        }
    }
}

