        // On a freshly deployed, uninitialized/just-initialized Product, the
        // accumulator has not been settled yet, so latestVersion must be 0 and
        // there must be no pending pre-position.
        uint256 latest = c.latestVersion();
        PrePosition memory p = c.pre();

        assert(latest == 0 && p.openPosition.maker.isZero() && p.openPosition.taker.isZero()
            && p.closePosition.maker.isZero() && p.closePosition.taker.isZero());
    }

    receive() external payable {}
}

